   await page.evaluate(()=>{
    window.geometryHands=[...document.querySelectorAll('.hand-track,.hand-cards,.mini-hand')].map(node=>({node,children:[...node.childNodes]}));for(const {node}of geometryHands)node.replaceChildren();
    PlayroomGameScreen.layoutScene(document.querySelector('#app'));
   });
   const hidden=await measure();
   assert(before.box.every((n,i)=>Math.abs(n-hidden.box[i])<=1),game+' field moved when hands disappeared: '+JSON.stringify({before,hidden}));
   await page.evaluate(()=>{for(const {node,children}of geometryHands)node.replaceChildren(...children);PlayroomGameScreen.layoutScene(document.querySelector('#app'));});
   await page.setViewportSize({width:844,height:390});
   await page.evaluate(()=>geometryRender());await page.evaluate(async()=>{await document.fonts.ready;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));});
   const landscape=await measure();assert(!landscape.error&&landscape.box[2]>0&&landscape.box[3]>0);
   if(['mage-brawl','domino'].includes(game)){
    await page.setViewportSize({width:740,height:390});await page.evaluate(()=>geometryRender());await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
    const compact=await page.evaluate(()=>{const field=document.querySelector('.layout-field').getBoundingClientRect(),own=document.querySelector('.layout-self').getBoundingClientRect(),tools=document.querySelector('.game-frame-tools').getBoundingClientRect(),pieces=[...document.querySelectorAll('.layout-self .hand-card,.layout-self .domino-tile')].map(el=>el.getBoundingClientRect()).filter(r=>r.width&&r.height);return {field:field.toJSON(),own:own.toJSON(),tools:tools.toJSON(),pieces:pieces.map(r=>r.toJSON())};});const evidence=path.resolve(root,'../tmp_files/ux-021/owner-iteration03/ui-platform'),engine=process.env.PLAYWRIGHT_MODULE?'webkit':'chromium';fs.mkdirSync(evidence,{recursive:true});fs.writeFileSync(path.join(evidence,engine+'-'+game+'-740.json'),JSON.stringify({game,compact,landscape},null,2));await page.screenshot({path:path.join(evidence,engine+'-'+game+'-740.png'),animations:'disabled'});assert(compact.pieces.length>0,'actual restored hands remain visible');assert(Math.abs(compact.field.width-compact.field.height)<2,JSON.stringify({game,compact,landscape}));assert(Math.abs(compact.field.height-landscape.box[3])<2,'landscape field keeps its height-bound square at740');assert(compact.pieces.every(piece=>piece.top>=compact.tools.bottom+6&&piece.bottom<=compact.own.bottom+1),'real Mage/Domino pieces fit below the reserved top-right tools '+JSON.stringify(compact));
   }
   await page.setViewportSize({width:390,height:844});
   await page.evaluate(()=>geometryRender());await page.evaluate(async()=>{await document.fonts.ready;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));});
   const restored=await measure();
   if(!before.box.every((n,i)=>Math.abs(n-restored.box[i])<=1)){const out=path.resolve(root,'../tmp_files/ux-021/common-game-header');fs.mkdirSync(out,{recursive:true});fs.writeFileSync(path.join(out,(process.env.PLAYWRIGHT_MODULE?'webkit':'chromium')+'-'+game+'-roundtrip.json'),JSON.stringify({before,landscape,restored},null,2));await page.screenshot({path:path.join(out,(process.env.PLAYWRIGHT_MODULE?'webkit':'chromium')+'-'+game+'-roundtrip.png'),animations:'disabled'});}
